import java.util.*;
import java.io.*;

public class Main {
    static final long MOD = 1000000007L;
    static final int maxN = 7;
    static final int max2N = 1 << maxN;
    static final int maxM = 100;
    static final int maxS = 64184;
    static final int[] sizes = {0, 5, 11, 37, 137, 821, 7529, 164184};
    static long[][] p = new long[maxN][maxM];
    static long[] prev = new long[maxS];
    static long[] cur = new long[maxS];
    static int len;
    static long[] bfs = new long[maxS];
    static int[] match = new int[maxS];
    static int[] ind = new int[maxS];
    static int[][] nextStates = new int[max2N][maxS];
    static long[] fixedSize = new long[maxN + 1];
    static long[] what = new long[maxS];
    static int SZ;
    static long[] prevArr = new long[maxS];

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        int m = n;
        prepare(n);
        for (int i = 0; i < n; i++) {
            String[] parts = br.readLine().trim().split("\\s+");
            for (int j = 0; j < m; j++) {
                long val = Long.parseLong(parts[j]);
                p[i][j] = val * modPow(100, MOD - 2) % MOD;
            }
        }
        System.out.println(compute(n, m));
    }

    static long modPow(long base, long exp) {
        long result = 1;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) result = (result * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return result;
    }

    static int bit(int n) {
        return 1 << n;
    }

    static long bitu128(int n) {
        long[] p = new long[128];
        p[n] = 1;
        return packBits(p);
    }

    static long packBits(long[] bits) {
        // Since Java doesn't have built-in bitset of 128 bits, simulate with two longs
        // For simplicity, we can store bits in a long array or use BitSet
        // But for this code, we will use BitSet
        BitSet bs = new BitSet(128);
        for (int i = 0; i < 128; i++) {
            if (bits[i] != 0) bs.set(i);
        }
        return bs.toLongArray()[0]; // placeholder, actual implementation needed
    }

    static boolean getBit(long state, int n) {
        // simulate getting bit n from the long representation
        // Since we packed bits, we need to unpack
        // For simplicity, we can store bits in BitSet
        // But for now, assume getBit is implemented
        // For the purpose of this code, we will implement a helper
        return (state & (1L << n)) != 0;
    }

    static void setBit(long[] bits, int n, boolean value) {
        if (value) bits[n / 64] |= 1L << (n % 64);
        else bits[n / 64] &= ~(1L << (n % 64));
    }

    static long getBitFromLong(long state, int n) {
        return (state & (1L << n)) != 0 ? 1L : 0L;
    }

    static long[] unpackBits(long state) {
        long[] bits = new long[128];
        for (int i = 0; i < 128; i++) {
            bits[i] = getBitFromLong(state, i);
        }
        return bits;
    }

    static long getIndex(long state) {
        int pos = 0;
        for (int i = 0; i < 128; i++) {
            long bitVal = getBitFromLong(state, i);
            pos = (pos * 2 + (int) bitVal) % SZ;
        }
        while (true) {
            if (what[pos] == state) {
                break;
            }
            if (what[pos] == 0) {
                what[pos] = state;
                bfs[len] = state;
                ind[pos] = len;
                ++len;
                return len - 1;
            }
            ++pos;
            if (pos == SZ) pos = 0;
        }
        return ind[pos];
    }

    static void prepare(int n) {
        int N = bit(n);
        Arrays.fill(fixedSize, 0);
        for (int mask = 0; mask < N; mask++) {
            int cnt = 0;
            for (int i = 0; i < n; i++) {
                if ((mask & bit(i)) != 0) cnt++;
            }
            fixedSize[cnt] |= bitu128(mask);
        }
        SZ = sizes[n];
        Arrays.fill(what, 0);
        len = 0;
        getIndex(1L);
        for (int k = 0; k < len; k++) {
            long state = bfs[k];
            long[] predHall = new long[n];
            Arrays.fill(predHall, 0);
            for (int mask = 0; mask < N; mask++) {
                if (anyBit(state, mask)) {
                    for (int i = 0; i < n; i++) {
                        predHall[i] |= bitu128(mask | bit(i));
                    }
                }
            }
            for (int mask = 0; mask < N; mask++) {
                long nxt = state;
                for (int i = 0; i < n; i++) {
                    if ((mask & bit(i)) != 0) {
                        nxt |= predHall[i];
                    }
                }
                nextStates[mask][k] = getIndex(nxt);
            }
            for (int i = n; i >= 0; i--) {
                if (anyBit(state, fixedSize[i])) {
                    match[k] = i;
