        // Implemented as:
        for (int i = 0; i < 128; i++) {
            if (((mask & (1L << i)) != 0) && ((state & (1L << i)) != 0)) {
                return true;
            }
        }
        return false;
    }

    static long compute(int n, int m) {
        Arrays.fill(prevArr, 0);
        prevArr[0] = 1;
        for (int k = 1; k < len; k++) {
