        int N = bit(n);
        for (int j = 0; j < m; j++) {
            Arrays.fill(cur, 0);
            for (int mask = 0; mask < N; mask++) {
                long prob = 1;
                for (int i = 0; i < n; i++) {
                    long val = (mask & bit(i)) != 0 ? p[i][j] : (MOD + 1 - p[i][j]) % MOD;
                    prob = (prob * val) % MOD;
                }
                for (int k = 0; k < len; k++) {
                    int nextStateIndex = nextStates[mask][k];
                    cur[nextStateIndex] = (cur[nextStateIndex] + prob * prevArr[k]) % MOD;
                }
            }
            System.arraycopy(cur, 0, prevArr, 0, len);
        }
        long answer = 0;
        for (int k = 0; k < len; k++) {
            if (match[k] == n) answer = (answer + prevArr[k]) % MOD;
        }
        return answer;
    }
}
